package com.zc.agent.core.modules.tool.controller;import com.zc.agent.core.common.response.ApiResponse;import com.zc.agent.core.modules.tool.repository.ToolInputObservationRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
/** Tool 输入契约观测和运营指标 API。 */
@RestController @RequestMapping("/api/core/tool-input-governance") public class ToolInputGovernanceController{private final ToolInputObservationRepository repo;public ToolInputGovernanceController(ToolInputObservationRepository repo){this.repo=repo;}@GetMapping("/observations")public ApiResponse<List<Map<String,Object>>> list(@RequestParam(required=false)String toolCode,@RequestParam(defaultValue="200")int limit){return ApiResponse.success(repo.list(toolCode,Math.min(Math.max(limit,1),1000)));}@GetMapping("/metrics")public ApiResponse<List<Map<String,Object>>> metrics(){return ApiResponse.success(repo.metrics());}}
